mapper.update:
UPDATE t_integration_script SET script_name=#{scriptName}, execution_stage=#{executionStage.code},
parameter_definition=#{parameterDefinition}, source_code=#{sourceCode}, description=#{description},
version=version+1, updated_by=#{updatedBy}, update_time=#{updateTime}
WHERE integration_script_id=#{row.integrationScriptId} AND version=#{row.version}
